{"date_raw": "25/03/2025", "meeting_date": "2025-03-25", "location": "Brussels", "organizations_raw": "METLEN Energy & Metals

						            	(Metlen)Nyrstar Netherlands (Holdings) B.V.

						            	(NNH)EUROMETAUX", "subject": "Impact of energy prices on the metal industry", "cabinet_member": "Aleksandra Baranska", "minutes_url": "https://ec.europa.eu/transparencyinitiative/meetings/exportmeetings.do?doc=c9b3595e-865b-4138-939b-40f2103b3692&host=no", "source_url": "https://ec.europa.eu/transparencyinitiative/meetings/meeting.do?host=5b0b3cd9-cf5f-48bf-b582-1d2dc6874a10&page=15", "actor_id": "COM_00006AC02D4F", "commissioner_name": "Teresa Ribera", "commissioner_portfolio": "clean, just and competitive transition in the second von der Leyen Commission", "host_id": "5b0b3cd9-cf5f-48bf-b582-1d2dc6874a10", "meeting_type": "cabinet", "id": "b2e0c941ad778ecc", "minutes_subject": "matter: Impact of energy prices on the metal industry.", "points_raised": null, "conclusions": ": N/A", "ares_number": null, "transparency_register_ids": [], "commission_representatives": [{"name": "(s):", "function": null}, {"name": "Executive Vice-President Ribera", "function": null}, {"name": "Aleksandra Barańska", "function": "Member of Cabinet"}, {"name": "Name(s) of the", "function": null}, {"name": "interest", "function": null}, {"name": "representative(s):", "function": null}, {"name": "Eurometaux", "function": null}, {"name": "Metlen Energy & Metals", "function": null}, {"name": "Nyrstar Netherlands (Holdings) B.V.", "function": null}, {"name": "Subject matter: Impact of energy prices on the metal industry.", "function": null}, {"name": "Main points", "function": null}, {"name": "raised and", "function": null}, {"name": "positions", "function": null}, {"name": "expressed:", "function": null}, {"name": "• The interlocutors explained that within their sector around", "function": null}, {"name": "85% of the processes depend on electricity. This makes the", "function": null}, {"name": "whole sector very sensitive to electricity prices. They stressed", "function": null}, {"name": "that the sector is exposed to global competition as the prices", "function": null}, {"name": "for the products are set on the global market.", "function": null}, {"name": "• The main concerns for Eurometaux are (1) the export of scrap", "function": null}, {"name": "metal to the US without tariffs", "function": null}, {"name": "(2) the indirect cost", "function": null}, {"name": "compensation", "function": null}, {"name": "and (3) the link of State aid to the Green Deal.", "function": null}, {"name": "• They asked the Commission to review the conditionalities for", "function": null}, {"name": "State aid for energy and the exclusive focus on green energy.", "function": null}, {"name": "The participants also called for extension of the compensation", "function": null}, {"name": "for indirect costs beyond 2030, possibly until 2035.", "function": null}, {"name": "• The EVP acknowledged that t he Commission is concerned", "function": null}, {"name": "both about the clima te goals and the problems faced by", "function": null}, {"name": "industry.", "function": null}, {"name": "• The EVP extended an invitation to actively participate in the", "function": null}, {"name": "ongoing public consultation on the State aid framework  and", "function": null}, {"name": "to raise the concerns in that context.", "function": null}, {"name": "Conclusions: N/A", "function": null}]}

