{"date_raw": "13/03/2025", "meeting_date": "2025-03-13", "location": "Brussels", "organizations_raw": "European Aluminium AISBL

						            	(European Aluminium)Befesa AluminioHammerer Aluminium Industries Holding GmbH

						            	(HAI)", "subject": "Exchange on challenges facing the aluminium industry in Europe", "cabinet_member": null, "minutes_url": "https://ec.europa.eu/transparencyinitiative/meetings/exportmeetings.do?doc=5989f498-b8d7-4564-9acf-a6e808653659&host=no", "source_url": "https://ec.europa.eu/transparencyinitiative/meetings/meeting.do?host=2db18618-dfac-418f-8791-d5ee44abf0db&page=6", "actor_id": "COM_00006AC02D4F", "commissioner_name": "Teresa Ribera", "commissioner_portfolio": "clean, just and competitive transition in the second von der Leyen Commission", "host_id": "2db18618-dfac-418f-8791-d5ee44abf0db", "meeting_type": "commissioner", "id": "d7ccb7afd8be0cfa", "minutes_subject": "matter: Exchange on challenges facing the aluminium industry in Europe", "points_raised": null, "conclusions": ": N/A", "ares_number": null, "transparency_register_ids": [], "commission_representatives": [{"name": "(s):", "function": null}, {"name": "Executive Vice-President Teresa Ribera", "function": null}, {"name": "Aleksandra Barańska", "function": "Member of Cabinet"}, {"name": "Name(s) of the", "function": null}, {"name": "interest", "function": null}, {"name": "representative(s):", "function": null}, {"name": "European Aluminium AISBL", "function": null}, {"name": "Hammerer Aluminium Industries Holding GmbH", "function": null}, {"name": "Befesa Aluminio", "function": null}, {"name": "Subject matter: Exchange on challenges facing the aluminium industry in Europe", "function": null}, {"name": "Main points", "function": null}, {"name": "raised and", "function": null}, {"name": "positions", "function": null}, {"name": "expressed:", "function": null}, {"name": "• The interlocutors raised the immediate ‘existential crisis’ facing", "function": null}, {"name": "European aluminium recyclers, due to the leakage of scrap metal", "function": null}, {"name": "out of Europe. While demand for the product remains high,", "function": null}, {"name": "suppliers of scrap are selling to other markets like China, India", "function": null}, {"name": "and the US, which offer higher prices while protecting their own", "function": null}, {"name": "industry, e.g. via subsidies or tariffs.", "function": null}, {"name": "• This market distortion undermines the production of recycled", "function": null}, {"name": "aluminium in the EU and increases the risk that the EU ends up", "function": null}, {"name": "re-importing products made from EU scrap (e.g. solar panels,", "function": null}, {"name": "electric cars). The new US tariffs would likely exacerbate the", "function": null}, {"name": "situation, as countries like China or Turkey will pivot from the", "function": null}, {"name": "US market to seek their scrap metal from the EU market instead.", "function": null}, {"name": "•  The stakeholders called on urgent action by the Commission in", "function": null}, {"name": "a matter of months at the latest. The association would favour an", "function": null}, {"name": "export duty as a solution, allowing them to compete on a level", "function": null}, {"name": "playing field. They were confident that the WTO conditions were", "function": null}, {"name": "met. In contrast, the Foreign Subsidies Regulation was not seen", "function": null}, {"name": "as a useful tool to address the issue, nor were the existing trade", "function": null}, {"name": "defence measures deemed sufficient.", "function": null}, {"name": "• They also flagged the issue of heavily subsidised Chinese", "function": null}, {"name": "investment in EU neighbouring countries like Serbia, which was", "function": null}, {"name": "further undershooting EU prices and undermining the EU", "function": null}, {"name": "internal market.", "function": null}, {"name": "• The interlocutors stressed that contacts with the new", "function": null}, {"name": "Commission had been positive. The spirit of the Clean Industrial", "function": null}, {"name": "Deal was encouraging.", "function": null}, {"name": "• EVP Ribera expressed the Commission’s support for the", "function": null}, {"name": "concerns. She stressed that any trade measures would have to be", "function": null}, {"name": "WTO compatible. She also pointed to the potential of the", "function": null}, {"name": "Circular Economy Act in the medium term.", "function": null}, {"name": "Conclusions: N/A", "function": null}]}

